//go:build amd64

package per

import (
	"github.com/thebagchi/asn1c-go/lib/cpu"
)

// How much input each assembly kernel handles per iteration.
const (
	NUMERIC_SSE2_CHARS = 16
	NUMERIC_SSE2_BYTES = 8
	NUMERIC_AVX2_CHARS = 64
	NUMERIC_AVX2_BYTES = 32
)

// The kernels are generated by avo from gen/numeric.go into numeric_amd64.s,
// with what every family shares in gen/main.go; the generator is ordinary Go,
// so the assembly is reviewed as the program that produced it. The
// declarations at the end of this file are what Go sees of the kernels, and
// go vet's asmdecl check holds them and the assembly's frames in step.
// Regenerate with "make generate" after editing anything under gen/.
//
//go:generate go run ./gen/main.go ./gen/numeric.go ./gen/hex.go ./gen/bin.go -only numeric -out numeric_amd64.s -pkg per

// The amd64 kernels. SSE2 is part of the architecture's baseline, so it can
// always run.
var (
	NUMERIC_SSE2 = &_Kernel{
		name:        NAME_SSE2,
		have:        true,
		encodeBlock: NUMERIC_SSE2_CHARS,
		decodeBlock: NUMERIC_SSE2_BYTES,
		encode:      _PackNumericSSE2,
		decode:      _UnpackNumericSSE2,
	}
	NUMERIC_AVX2 = &_Kernel{
		name:        NAME_AVX2,
		have:        cpu.HAS_AVX2,
		encodeBlock: NUMERIC_AVX2_CHARS,
		decodeBlock: NUMERIC_AVX2_BYTES,
		encode:      _PackNumericAVX2,
		decode:      _UnpackNumericAVX2,
	}
)

// _NumericKernels lists every kernel amd64 has, narrowest first.
//
// Revisions:
//   - 2026-09-23 05:40: initial creation
//   - 2026-09-24 01:40: begins with the Go kernel, like every architecture
func _NumericKernels() []*_Kernel {
	return []*_Kernel{NUMERIC_GO, NUMERIC_SSE2, NUMERIC_AVX2}
}

// _PackNumeric packs src with the assembly kernels in turn, widest first: the
// kernel init selected over whole blocks, then the SSE2 kernel over a block it
// left behind. Each stops at the first block holding a character outside the
// alphabet, so the result is every block up to it; the caller finishes with
// the Go kernel, and kernel.go says why.
//
// The kernels are called by name rather than through the table's encode
// field for the reason bitbuffer._RunShift gives: a call through a function
// value would move the caller's stack scratch to the heap on every call. The
// AVX2 kernel ends in VZEROUPPER, so the legacy-encoded SSE2 kernel after it
// pays no transition.
//
// Revisions:
//   - 2026-09-23 05:40: initial creation
//   - 2026-09-23 06:05: calls the kernels by name rather than through the
//     table, so the caller's scratch stays on its stack, and lets SSE2 take
//     the half block AVX2 cannot
//   - 2026-09-24 01:10: dispatches on the kernel init selected rather than on
//     the feature bits, so the selection is made in one place
//   - 2026-09-24 01:40: finishes with the Go kernel, so the caller is left at
//     most one character
//   - 2026-09-24 02:00: the assembly kernels only, again; the Go kernel moved
//     to the caller
func _PackNumeric(dst, src []byte) int {
	var (
		done int
	)

	if NUMERIC_KERNEL == NUMERIC_AVX2 {
		done = _PackNumericAVX2(dst, src)
	}

	if rest := src[done:]; len(rest) >= NUMERIC_SSE2_CHARS {
		done += _PackNumericSSE2(dst[done/NUMERIC_PAIR:], rest)
	}

	return done
}

// _UnpackNumeric unpacks src with every kernel in turn, on the same terms as
// _PackNumeric.
//
// Revisions:
//   - 2026-09-23 05:40: initial creation
//   - 2026-09-23 06:05: calls the kernels by name and lets SSE2 take the half
//     block AVX2 cannot
//   - 2026-09-24 01:10: dispatches on the kernel init selected
//   - 2026-09-24 01:40: finishes with the Go kernel
//   - 2026-09-24 02:00: the assembly kernels only, again
func _UnpackNumeric(dst, src []byte) int {
	var (
		done int
	)

	if NUMERIC_KERNEL == NUMERIC_AVX2 {
		done = _UnpackNumericAVX2(dst, src)
	}

	if rest := src[done:]; len(rest) >= NUMERIC_SSE2_BYTES {
		done += _UnpackNumericSSE2(dst[done*NUMERIC_PAIR:], rest)
	}

	return done
}

// _PackNumericSSE2 packs pairs of NumericString characters from src into
// nibbles in dst, sixteen characters per iteration, and returns how many
// characters it consumed: a multiple of sixteen, short of len(src) when a block
// holds a character outside the alphabet. len(dst) must be at least len(src)/2.
// It is declared noescape so a caller's stack buffer stays where it is, as are
// the three below.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _PackNumericSSE2(dst, src []byte) int

// _PackNumericAVX2 is _PackNumericSSE2 at sixty-four characters per iteration.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _PackNumericAVX2(dst, src []byte) int

// _UnpackNumericSSE2 unpacks nibbles from src into NumericString characters in
// dst, eight bytes per iteration, and returns how many bytes it consumed: a
// multiple of eight, short of len(src) when a block holds a nibble outside the
// alphabet. len(dst) must be at least 2*len(src).
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _UnpackNumericSSE2(dst, src []byte) int

// _UnpackNumericAVX2 is _UnpackNumericSSE2 at thirty-two bytes per iteration.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _UnpackNumericAVX2(dst, src []byte) int
